<?php
$item = $data['item']; $editing = $item !== []; $kind = $data['kind']; $values = $data['values'] ?? $item;
$value = static fn (string $key): string => (string) ($values[$key] ?? '');
$selected = $values['module_ids'] ?? array_column($item['modules'] ?? [], 'id');
$selected = array_map('strval', array_filter($selected, 'is_scalar'));
?>
<section class="page-band"><div class="site-shell"><a href="/dashboard/admin/training">Back to training management</a><h1 class="mt-3"><?= $escape($data['title']) ?></h1><?php if ($editing): ?><p><span class="status-badge"><?= $escape(ucfirst($item['status'])) ?></span> · Revision <?= (int) $item['revision'] ?></p><?php endif; ?></div></section>
<div class="site-shell section-space">
<?php if ($data['notice'] !== ''): ?><p class="auth-notice" role="status"><?= $escape($data['notice']) ?></p><?php endif; ?>
<?php if ($data['error'] !== ''): ?><div class="alert alert-danger" role="alert"><?= $escape($data['error']) ?></div><?php endif; ?>
<div class="row g-4"><div class="col-lg-8"><form class="form-panel auth-form" method="post" action="/dashboard/admin/training">
<input type="hidden" name="_csrf" value="<?= $escape($data['csrf']) ?>"><input type="hidden" name="kind" value="<?= $escape($kind) ?>"><input type="hidden" name="action" value="save"><?php if ($editing): ?><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><input type="hidden" name="revision" value="<?= (int) $item['revision'] ?>"><?php endif; ?>
<div><label class="form-label" for="training-title">Title (required)</label><input class="form-control" id="training-title" name="title" maxlength="200" value="<?= $escape($value('title')) ?>" required></div>
<div><label class="form-label" for="training-description">Description (required)</label><textarea class="form-control" id="training-description" name="description" rows="5" maxlength="<?= $kind === 'module' ? 6000 : 4000 ?>" required><?= $escape($value('description')) ?></textarea></div>
<?php if ($kind === 'module'): ?>
<?php foreach (['category' => ['Category', 120], 'target_participants' => ['Target participants', 300], 'duration' => ['Duration (for example, 2 days)', 120]] as $key => [$label, $limit]): ?><div><label class="form-label" for="training-<?= $key ?>"><?= $label ?> (required)</label><input class="form-control" id="training-<?= $key ?>" name="<?= $key ?>" maxlength="<?= $limit ?>" value="<?= $escape($value($key)) ?>" required></div><?php endforeach; ?>
<div><label class="form-label" for="training-format">Delivery format</label><select class="form-select" id="training-format" name="delivery_format" required><?php foreach (['on_site' => 'On-site', 'online' => 'Online', 'hybrid' => 'Hybrid'] as $key => $label): ?><option value="<?= $key ?>"<?= $value('delivery_format') === $key ? ' selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></div>
<?php foreach (['objectives' => ['Learning objectives', 4000], 'prerequisites' => ['Prerequisites', 2000], 'materials_metadata' => ['Public training materials description', 2000]] as $key => [$label, $limit]): ?><div><label class="form-label" for="training-<?= $key ?>"><?= $label ?><?= $key === 'objectives' ? ' (required)' : '' ?></label><textarea class="form-control" id="training-<?= $key ?>" name="<?= $key ?>" rows="4" maxlength="<?= $limit ?>"<?= $key === 'objectives' ? ' required' : '' ?>><?= $escape($value($key)) ?></textarea><?php if ($key === 'materials_metadata'): ?><p class="form-text">Describe materials only. Do not include private file paths, credentials or confidential information. This text appears in the public catalogue.</p><?php endif; ?></div><?php endforeach; ?>
<?php else: ?>
<fieldset><legend class="h5">Ordered package modules</legend><p>Select up to 20 modules. Use the position fields to set their order; each selected module needs a unique position.</p>
<?php if ($data['modules'] === []): ?><p data-empty-state>No modules exist yet. <a href="/dashboard/admin/training?kind=module&amp;new=1">Create a module first</a>.</p><?php endif; ?>
<?php foreach ($data['modules'] as $module): $position = array_search((string) $module['id'], $selected, true); ?><div class="row g-2 align-items-center mb-3"><div class="col-8"><div class="form-check"><input class="form-check-input" type="checkbox" id="training-member-<?= (int) $module['id'] ?>" name="module_ids[]" value="<?= (int) $module['id'] ?>"<?= $position !== false ? ' checked' : '' ?>><label class="form-check-label" for="training-member-<?= (int) $module['id'] ?>"><?= $escape($module['title']) ?> (<?= $escape($module['status']) ?>)</label></div></div><div class="col-4"><label class="form-label small" for="training-order-<?= (int) $module['id'] ?>">Position</label><input class="form-control" type="number" min="1" max="20" name="module_order[<?= (int) $module['id'] ?>]" id="training-order-<?= (int) $module['id'] ?>" value="<?= $position === false ? '' : (int) $position + 1 ?>"></div></div><?php endforeach; ?></fieldset>
<?php endif; ?><p>Saving published content returns it to draft. Packages can be published only when all included modules are published.</p><button class="btn button button-primary" type="submit"><?= $editing ? 'Save changes as draft' : 'Create draft' ?></button></form></div>
<?php if ($editing): ?><aside class="col-lg-4"><section class="form-panel"><h2 class="h4">Publication</h2><p>Complete every required detail before publishing. Review public materials descriptions for confidential information.</p><form method="post" action="/dashboard/admin/training" class="d-flex flex-wrap gap-2"><input type="hidden" name="_csrf" value="<?= $escape($data['csrf']) ?>"><input type="hidden" name="kind" value="<?= $escape($kind) ?>"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><input type="hidden" name="revision" value="<?= (int) $item['revision'] ?>"><input type="hidden" name="action" value="publish"><?php foreach (['published' => 'Publish', 'draft' => 'Return to draft', 'archived' => 'Archive'] as $status => $label): ?><?php if ($status !== $item['status']): ?><button class="btn button button-outline" name="status" value="<?= $status ?>"><?= $label ?></button><?php endif; ?><?php endforeach; ?></form></section></aside><?php endif; ?></div></div>
